package com.asmj.marketplace.service.controller;
import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.service.model.*;import com.asmj.marketplace.service.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/admin/services") @PreAuthorize("hasRole('ADMIN')") @RequiredArgsConstructor public class ServiceAdminController{final ServiceListingRepository services;final ServiceBookingRepository bookings;@GetMapping public ApiResponse<?> all(){return ApiResponse.ok("",services.findAll());}@PutMapping("/{id}/approval") public ApiResponse<?> approval(@PathVariable String id,@RequestParam boolean approved){ServiceListing s=services.findById(id).orElseThrow();s.setApproved(approved);s.setActive(approved);s.setUpdatedAt(Instant.now());return ApiResponse.ok("",services.save(s));}@GetMapping("/bookings")public ApiResponse<?> bookings(){return ApiResponse.ok("",bookings.findAll());}}
